     1	import { Injectable, inject } from '@angular/core';
     2	import { CanActivateFn, Router } from '@angular/router';
     3	
     4	/** The values typed into the checkout form; kept as they are typed. */
     5	export interface CheckoutValues {
     6	  firstName: string;
     7	  lastName: string;
     8	  email: string;
     9	  confirmEmail: string;
    10	  phone: string;
    11	  terms: boolean;
    12	}
    13	
    14	/** The booking: one screening, the seats selected for it and, once paid, the payer's email. */
    15	export interface Booking {
    16	  screeningId: number;
    17	  /** Seat identifiers (`R<row>C<column>`); a couch contributes both of its identifiers. */
    18	  seats: string[];
    19	  /** The checkout form values, when the customer has typed any. */
    20	  checkout?: CheckoutValues;
    21	  /** Set once the booking is paid; a paid booking is no longer in progress. */
    22	  paidEmail?: string;
    23	}
    24	
    25	const STORAGE_KEY = 'cinescope.booking';
    26	
    27	function isCheckoutValues(value: unknown): value is CheckoutValues {
    28	  if (typeof value !== 'object' || value === null) {
    29	    return false;
    30	  }
    31	  const checkout = value as Record<keyof CheckoutValues, unknown>;
    32	  return (
    33	    typeof checkout.firstName === 'string' &&
    34	    typeof checkout.lastName === 'string' &&
    35	    typeof checkout.email === 'string' &&
    36	    typeof checkout.confirmEmail === 'string' &&
    37	    typeof checkout.phone === 'string' &&
    38	    typeof checkout.terms === 'boolean'
    39	  );
    40	}
    41	
    42	function parseBooking(raw: string | null): Booking | null {
    43	  if (!raw) {
    44	    return null;
    45	  }
    46	  try {
    47	    const value = JSON.parse(raw) as Partial<Booking>;
    48	    if (typeof value.screeningId !== 'number' || !Array.isArray(value.seats)) {
    49	      return null;
    50	    }
    51	    const seats = value.seats;
    52	    if (!seats.every((seat) => typeof seat === 'string')) {
    53	      return null;
    54	    }
    55	    const booking: Booking = { screeningId: value.screeningId, seats };
    56	    if (isCheckoutValues(value.checkout)) {
    57	      booking.checkout = value.checkout;
    58	    }
    59	    if (typeof value.paidEmail === 'string') {
    60	      booking.paidEmail = value.paidEmail;
    61	    }
    62	    return booking;
    63	  } catch {
    64	    return null;
    65	  }
    66	}
    67	
    68	/** Keeps the booking in `sessionStorage`, so it survives a reload. */
    69	@Injectable({ providedIn: 'root' })
    70	export class BookingService {
    71	  /** The stored booking, or null when there is none. */
    72	  current(): Booking | null {
    73	    return parseBooking(sessionStorage.getItem(STORAGE_KEY));
    74	  }
    75	
    76	  save(booking: Booking): void {
    77	    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
    78	  }
    79	
    80	  clear(): void {
    81	    sessionStorage.removeItem(STORAGE_KEY);
    82	  }
    83	}
    84	
    85	/**
    86	 * Lets the summary and checkout screens open only for an unpaid booking of the screening in the
    87	 * route with at least one seat; otherwise redirects to `/`.
    88	 */
    89	export const bookingGuard: CanActivateFn = (route) => {
    90	  const booking = inject(BookingService).current();
    91	  const allowed =
    92	    booking !== null &&
    93	    String(booking.screeningId) === route.paramMap.get('id') &&
    94	    booking.seats.length > 0 &&
    95	    booking.paidEmail === undefined;
    96	  return allowed ? true : inject(Router).createUrlTree(['/']);
    97	};
    98	
    99	/** Lets the confirmation screen open only for a paid booking; otherwise redirects to `/`. */
   100	export const paidBookingGuard: CanActivateFn = () => {
   101	  const booking = inject(BookingService).current();
   102	  return booking?.paidEmail !== undefined ? true : inject(Router).createUrlTree(['/']);
   103	};
==== dates.ts
     1	export const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
     2	const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
     3	
     4	/** Formats a screening as `<Weekday> <D> <Mon> <HH:mm>`, e.g. `Tuesday 15 Sep 16:00`. */
     5	export function formatShowDate(isoDate: string, time: string): string {
     6	  const date = parseIsoDate(isoDate);
     7	  if (!date) {
     8	    throw new Error(`Invalid ISO date: ${isoDate}`);
     9	  }
    10	  return `${WEEKDAYS[date.getDay()]} ${date.getDate()} ${MONTHS[date.getMonth()]} ${time}`;
    11	}
    12	
    13	/** Start of the given day in the browser's local time zone. */
    14	export function startOfDay(date: Date): Date {
    15	  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
    16	}
    17	
    18	export function addDays(date: Date, days: number): Date {
    19	  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
    20	}
    21	
    22	/** Formats a date as `YYYY-MM-DD` using local calendar fields (not UTC). */
    23	export function toIsoDate(date: Date): string {
    24	  const pad = (n: number) => String(n).padStart(2, '0');
    25	  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
    26	}
    27	
    28	/** Parses a strict `YYYY-MM-DD` string; returns null when missing or not a real calendar date. */
    29	export function parseIsoDate(value: string | null): Date | null {
    30	  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    31	    return null;
    32	  }
    33	  const [year, month, day] = value.split('-').map(Number);
    34	  const date = new Date(year, month - 1, day);
    35	  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day ? date : null;
    36	}
