==== tickets.ts
     1	import { COUCH_ROW, seatId } from './seat-selection/auditorium';
     2	
     3	/** Price of a couch in row 15, per couch (two seats), in PLN. */
     4	export const COUCH_PRICE = 89;
     5	
     6	/** One line of the summary: a single seat or a couch, with its price. */
     7	export interface Ticket {
     8	  row: number;
     9	  /** The column number of a seat, or `Couch <a>-<b>` for a couch. */
    10	  seat: string;
    11	  /** The seat identifiers the ticket covers: one for a seat, two for a couch. */
    12	  seatIds: string[];
    13	  /** Price in PLN. */
    14	  price: number;
    15	}
    16	
    17	/** Price of a single seat in the given row, in PLN. Accessible seats are in row 1. */
    18	export function seatPrice(row: number): number {
    19	  if (row <= 5) {
    20	    return 25;
    21	  }
    22	  if (row <= 10) {
    23	    return 32;
    24	  }
    25	  return 39;
    26	}
    27	
    28	/** Formats a price in PLN with two decimals and the suffix, e.g. `25.00 PLN`. */
    29	export function formatPrice(pln: number): string {
    30	  return `${pln.toFixed(2)} PLN`;
    31	}
    32	
    33	/** Sum of the prices of the tickets, in PLN. */
    34	export function totalOf(tickets: readonly Ticket[]): number {
    35	  return tickets.reduce((sum, ticket) => sum + ticket.price, 0);
    36	}
    37	
    38	function parseSeatId(id: string): { row: number; column: number } | null {
    39	  const match = /^R(\d+)C(\d+)$/.exec(id);
    40	  return match ? { row: Number(match[1]), column: Number(match[2]) } : null;
    41	}
    42	
    43	/**
    44	 * Turns seat identifiers into summary tickets, ordered by row and then by column. In the couch
    45	 * row, each couch (columns 1–2, 3–4, …) is one ticket, so its second seat is not listed again.
    46	 */
    47	export function ticketsOf(seatIds: readonly string[]): Ticket[] {
    48	  const seats = seatIds
    49	    .map(parseSeatId)
    50	    .filter((seat): seat is { row: number; column: number } => seat !== null)
    51	    .sort((a, b) => a.row - b.row || a.column - b.column);
    52	
    53	  const tickets: Ticket[] = [];
    54	  for (const { row, column } of seats) {
    55	    if (row === COUCH_ROW) {
    56	      if (column % 2 === 1) {
    57	        tickets.push({
    58	          row,
    59	          seat: `Couch ${column}-${column + 1}`,
    60	          seatIds: [seatId(row, column), seatId(row, column + 1)],
    61	          price: COUCH_PRICE,
    62	        });
    63	      }
    64	      continue;
    65	    }
    66	    tickets.push({ row, seat: String(column), seatIds: [seatId(row, column)], price: seatPrice(row) });
    67	  }
    68	  return tickets;
    69	}

