    10	import { ActivatedRoute, Router } from '@angular/router';
    11	import { forkJoin } from 'rxjs';
    12	import { API_URL } from '../api';
    13	import { WEEKDAYS, addDays, parseIsoDate, startOfDay, toIsoDate } from '../dates';
    14	import { Movie, Screening } from '../models';
    15	
    16	type LoadState = 'loading' | 'loaded' | 'error';
    17	
    18	@Component({
    19	  selector: 'app-movie-list',
    20	  imports: [MatButtonModule, MatCardModule, MatDatepickerModule, MatFormFieldModule, MatInputModule, MatProgressSpinnerModule],
    21	  templateUrl: './movie-list.html',
    22	  styleUrl: './movie-list.scss',
    23	})
    24	export class MovieList {
    25	  private readonly http = inject(HttpClient);
    26	  private readonly router = inject(Router);
    27	  private readonly route = inject(ActivatedRoute);
    28	  private readonly destroyRef = inject(DestroyRef);
    29	
    30	  protected readonly today = startOfDay(new Date());
    31	
    32	  /** Today and the next four days, as shown in the day picker. */
    33	  protected readonly days = [0, 1, 2, 3, 4].map((offset) => {
    34	    const date = addDays(this.today, offset);
    35	    return { iso: toIsoDate(date), label: offset === 0 ? 'Today' : WEEKDAYS[date.getDay()] };
    36	  });
    37	
    38	  private readonly queryParams = toSignal(this.route.queryParamMap, { requireSync: true });
    39	
    40	  /** The `?date=` day if valid and not in the past, otherwise today. */
    41	  protected readonly selectedDate = computed(() => {
    42	    const requested = parseIsoDate(this.queryParams().get('date'));
    43	    return requested && requested >= this.today ? requested : this.today;
    44	  });
    45	  protected readonly selectedIso = computed(() => toIsoDate(this.selectedDate()));
    46	
    47	  /** The datepicker shows the date only when it is not one of the five day buttons. */
    48	  protected readonly pickedDate = computed(() =>
    49	    this.days.some((day) => day.iso === this.selectedIso()) ? null : this.selectedDate(),
    50	  );
    51	
    52	  protected readonly state = signal<LoadState>('loading');
    53	  private readonly movies = signal<Movie[]>([]);
    54	  private readonly screenings = signal<Screening[]>([]);
    55	
    56	  protected readonly visibleMovies = computed(() => {
    57	    const iso = this.selectedIso();
    58	    const dayScreenings = this.screenings().filter((screening) => screening.date === iso);
    59	    return this.movies()
    60	      .map((movie) => ({
    61	        movie,
    62	        screenings: dayScreenings
    63	          .filter((screening) => screening.movieId === movie.id)
    64	          .sort((a, b) => a.time.localeCompare(b.time)),
    65	      }))
    66	      .filter((entry) => entry.screenings.length > 0);
    67	  });
    68	
    69	  constructor() {
    70	    this.load();
    71	  }
    72	
    73	  protected load(): void {
    74	    this.state.set('loading');
    75	    forkJoin({
    76	      movies: this.http.get<Movie[]>(`${API_URL}/movies`),
    77	      screenings: this.http.get<Screening[]>(`${API_URL}/screenings`),
    78	    })
    79	      .pipe(takeUntilDestroyed(this.destroyRef))
    80	      .subscribe({
    81	        next: ({ movies, screenings }) => {
    82	          this.movies.set(movies);
    83	          this.screenings.set(screenings);
    84	          this.state.set('loaded');
    85	        },
    86	        error: () => this.state.set('error'),
    87	      });
    88	  }
    89	
    90	  protected selectDay(iso: string): void {
    91	    void this.router.navigate([], { relativeTo: this.route, queryParams: { date: iso } });
    92	  }
    93	
    94	  protected selectDate(date: Date | null): void {
    95	    if (!date || date < this.today) {
    96	      return;
    97	    }
    98	    this.selectDay(toIsoDate(date));
    99	  }
   100	
   101	  protected openScreening(id: number): void {
   102	    void this.router.navigate(['/screenings', id, 'seats']);
   103	  }
   104	}
