     1	/** Seat state as drawn on the map. */
     2	export type SeatState = 'available' | 'accessible' | 'selected' | 'unavailable';
     3	
     4	/** A couch is never accessible. */
     5	export type CouchState = Exclude<SeatState, 'accessible'>;
     6	
     7	export const ROW_COUNT = 15;
     8	export const COLUMN_COUNT = 24;
     9	
    10	/** Rows 1 to 10 have no seats in columns 1 to 4: that space is the entrance. */
    11	const ENTRANCE_LAST_ROW = 10;
    12	export const COUCH_ROW = 15;
    13	const ACCESSIBLE_ROW = 1;
    14	const ACCESSIBLE_FIRST_COLUMN = 10;
    15	const ACCESSIBLE_LAST_COLUMN = 15;
    16	
    17	/**
    18	 * The auditorium is a CSS grid with 28 tracks per row: track 1 is the left row label, tracks
