    90	 * 3–4, … 23–24).
    91	 */
    92	export function buildAuditorium(
    93	  occupiedSeats: readonly string[],
    94	  selectedSeats: ReadonlySet<string> = new Set(),
    95	): AuditoriumRow[] {
    96	  const occupied = new Set(occupiedSeats);
    97	  const isOccupied = (row: number, column: number) => occupied.has(seatId(row, column));
    98	  const isSelected = (row: number, column: number) => selectedSeats.has(seatId(row, column));
    99	
   100	  return Array.from({ length: ROW_COUNT }, (_, index) => {
   101	    const row = index + 1;
   102	    const cells: AuditoriumCell[] = [
   103	      { kind: 'aisle', row, gridColumn: trackSpan(LEFT_AISLE_TRACK) },
   104	      { kind: 'aisle', row, gridColumn: trackSpan(RIGHT_AISLE_TRACK) },
   105	    ];
