   115	            kind: 'couch',
   116	            row,
   117	            columnStart: column,
   118	            columnEnd: column + 1,
   119	            gridColumn: columnSpan(column, column + 1),
   120	            state: couchState(
   121	              isOccupied(row, column) || isOccupied(row, column + 1),
   122	              isSelected(row, column) || isSelected(row, column + 1),
   123	            ),
   124	          });
   125	        }
   126	        continue;
   127	      }
   128	
   129	      cells.push({
   130	        kind: 'seat',
   131	        row,
   132	        column,
   133	        gridColumn: columnSpan(column, column),
   134	        state: seatState(row, column, isOccupied(row, column), isSelected(row, column)),
   135	      });
   136	    }
   137	
   138	    return { row, cells };
   139	  });
   140	}
   141	
   142	function couchState(occupied: boolean, selected: boolean): CouchState {
   143	  if (occupied) {
   144	    return 'unavailable';
   145	  }
   146	  return selected ? 'selected' : 'available';
   147	}
   148	
   149	function seatState(row: number, column: number, occupied: boolean, selected: boolean): SeatState {
   150	  if (occupied) {
   151	    return 'unavailable';
   152	  }
   153	  if (selected) {
   154	    return 'selected';
   155	  }
   156	  const accessible =
   157	    row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN;
