     1	import { FormControl, FormGroup, ValidatorFn, Validators } from '@angular/forms';
     2	import { CheckoutValues } from '../booking';
     3	
     4	export type CheckoutField = keyof CheckoutValues;
     5	
     6	export type CheckoutForm = FormGroup<{ [K in CheckoutField]: FormControl<CheckoutValues[K]> }>;
     7	
     8	/** One or more characters without spaces or `@`, then `@`, then a domain with a dot that has characters on each side. */
     9	const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    10	const PHONE_PATTERN = /^\d{9}$/;
    11	
    12	/** Messages by validation error key; the first key of a field that has a message is shown. */
    13	const MESSAGES: Record<CheckoutField, Partial<Record<string, string>>> = {
    14	  firstName: {
    15	    required: 'First name is required',
    16	    minlength: 'First name must be at least 2 characters',
    17	  },
    18	  lastName: {
    19	    required: 'Last name is required',
    20	    minlength: 'Last name must be at least 2 characters',
    21	  },
    22	  email: {
    23	    required: 'Email is required',
    24	    pattern: 'Enter a valid email address',
    25	  },
    26	  confirmEmail: {
    27	    required: 'Confirm email is required',
    28	    mismatch: 'Email addresses do not match',
    29	  },
    30	  phone: {
    31	    pattern: 'Phone number must be exactly 9 digits',
    32	  },
    33	  terms: {
    34	    required: 'You must accept the terms and conditions',
    35	  },
    36	};
    37	
    38	const EMPTY_VALUES: CheckoutValues = {
    39	  firstName: '',
    40	  lastName: '',
    41	  email: '',
    42	  confirmEmail: '',
    43	  phone: '',
    44	  terms: false,
    45	};
    46	
    47	/** Confirm email must equal Email as typed; an empty confirmation is reported by `required` instead. */
    48	const matchesEmail: ValidatorFn = (control) => {
    49	  const email = control.parent?.get('email')?.value;
    50	  return control.value === '' || control.value === email ? null : { mismatch: true };
    51	};
    52	
    53	/** Builds the checkout form with the given values; without values the form is empty. */
    54	export function createCheckoutForm(values: CheckoutValues | undefined): CheckoutForm {
    55	  const initial = values ?? EMPTY_VALUES;
    56	  const form: CheckoutForm = new FormGroup({
    57	    firstName: new FormControl(initial.firstName, {
    58	      nonNullable: true,
    59	      validators: [Validators.required, Validators.minLength(2)],
    60	    }),
    61	    lastName: new FormControl(initial.lastName, {
    62	      nonNullable: true,
    63	      validators: [Validators.required, Validators.minLength(2)],
    64	    }),
    65	    email: new FormControl(initial.email, {
    66	      nonNullable: true,
    67	      validators: [Validators.required, Validators.pattern(EMAIL_PATTERN)],
    68	    }),
    69	    confirmEmail: new FormControl(initial.confirmEmail, {
    70	      nonNullable: true,
    71	      validators: [Validators.required, matchesEmail],
    72	    }),
    73	    phone: new FormControl(initial.phone, {
    74	      nonNullable: true,
    75	      validators: [Validators.pattern(PHONE_PATTERN)],
    76	    }),
    77	    terms: new FormControl(initial.terms, {
    78	      nonNullable: true,
    79	      validators: [Validators.requiredTrue],
    80	    }),
    81	  });
    82	
    83	  // The confirmation is compared with Email, so it is checked again whenever Email changes. The
    84	  // initial check runs now because the control had no parent when it was created.
    85	  form.controls.email.valueChanges.subscribe(() =>
    86	    form.controls.confirmEmail.updateValueAndValidity(),
    87	  );
    88	  form.controls.confirmEmail.updateValueAndValidity({ emitEvent: false });
    89	  return form;
    90	}
    91	
    92	/**
    93	 * The message shown for a field: only once the field has been left, and at most one. Null when
    94	 * the field is valid or has not been left yet.
    95	 */
    96	export function checkoutErrorMessage(form: CheckoutForm, field: CheckoutField): string | null {
    97	  const control = form.controls[field];
    98	  if (!control.touched || !control.errors) {
    99	    return null;
   100	  }
   101	  for (const key of Object.keys(control.errors)) {
   102	    const message = MESSAGES[field][key];
   103	    if (message) {
   104	      return message;
   105	    }
   106	  }
   107	  return null;
   108	}

